function smallestAfterSwaps(s: string, pairs: number[][]): string {
  const n = s.length;
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of pairs) { adj[a].push(b); adj[b].push(a); }
  const out: string[] = [];
  for (let i = 0; i < n; i++) {
    const seen = new Set([i]), stack = [i];
    while (stack.length) {
      const u = stack.pop()!;
      for (const v of adj[u]) if (!seen.has(v)) { seen.add(v); stack.push(v); }
    }
    const idx = [...seen].sort((x, y) => x - y);
    const chars = idx.map(j => s[j]).sort();
    out.push(chars[idx.indexOf(i)]);
  }
  return out.join("");
}

