function smallestAfterSwaps(s: string, pairs: number[][]): string {
  const n = s.length;
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x: number): number => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  for (const [a, b] of pairs) parent[find(a)] = find(b);
  const groups = new Map<number, number[]>();
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root)!.push(i); // indexes arrive in increasing order
  }
  const out = new Array<string>(n);
  for (const idx of groups.values()) {
    const chars = idx.map(i => s[i]).sort();
    idx.forEach((pos, k) => { out[pos] = chars[k]; });
  }
  return out.join("");
}

